/* @lc app=leetcode id=3413 lang=kotlin */ class Solution { fun ub(a: List<Int>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun f(sg: List<IntArray>, k: Int): Long = sg.map { it[0] }.let { ls -> sg.runningFold(0L) { s, x -> s + (x[1] - x[0] + 1).toLong() * x[2] }.let { pre -> sg.indices.maxOf { i -> (sg[i][0].toLong() + k - 1).let { e -> ub(ls, e).let { jr -> pre[jr] - pre[i] - maxOf(0L, sg[jr - 1][1] - e) * sg[jr - 1][2] } } } } } fun maximumCoins(coins: Array<IntArray>, k: Int): Long = maxOf(f(coins.sortedBy { it[0] }, k), f(coins.map { intArrayOf(-it[1], -it[0], it[2]) }.sortedBy { it[0] }, k)) }